from pathlib import Path
import json,hashlib,statistics,subprocess,ast
p=Path(__file__).resolve().parent;root=p.parents[2]
verified=[]
for name in ['cta_row_counts','clean_claimrow_dependency','claimrow_quota']:
 f=p/f'{name}_native_unlimited_f24.json';r=json.loads(f.read_text());assert r['complete']
 for lib in r['libraries']:assert hashlib.sha256((root/lib['path']).read_bytes()).hexdigest()==lib['sha256']
 verified.append(f.name)
r=json.loads((p/'claimrow_quota_native_unlimited_f24.json').read_text());assert r['header_sha256']==hashlib.sha256((p/'claimrow_quota.cuh').read_bytes()).hexdigest();d=r['packet_plan_validation'];assert d['exact_cpu_match'] and d['ready_epochs_match']
means=[statistics.mean(x['us']) for x in r['passes']]
a=dict(pass_means_us=means,mean_us=statistics.mean(means),focused_tests=2,cpu_exact_partition_cases=180,actual_plan=d,header_actual_library_sha_verified=True,retained=False,scope='normal GPU3 singledevice farHBM only; no100GB or physical link result')
(p/'claimrow_quota_audit.json').write_text(json.dumps(a,indent=2)+'\n')
probe=json.loads((p/'clean_claimrow_dependency_native_unlimited_f24.json').read_text());pd=probe['claimrow_dependency'];oldpair=statistics.mean(x['producer_ctas'] for x in probe['final_step_dependency']['rows']);newpair=statistics.mean(x['producer_ctas'] for x in pd['first_far_pair_dependencies'])
(p/'CLAIMROW_QUOTA_20261104.md').write_text(f'''# 认领行局部性与并行前缀配额\n\n先用原clean kernel事件外导出实际row_slot_base/remap（32步一pass、正常GPU3），无生产修改。实际末步unique{pd['unique']}、far引用{pd['far_references']}；将每个20页包交包首slot的claimrow%108可把自用引用{pd['old_self_references']}→{pd['new_self_references']}（约0.90%→49.01%），首次far pair涉及producer平均{oldpair:.6f}→{newpair:.6f}。但每CTA负载30–160包、均82.176，约1.95倍尾部，未直接构建这个无配额形式。这是末步算术分析，不是时间/带宽预测。\n\n新完整kernel从clean冻结头出发，在resolve已产生本CTA shared row prefix之后、LRU覆盖shared之前，线程并行计算各owner已有区间包数，两个CTA scan得到excess/deficit prefix，再由线程并行逆查源owner与其至多约10个行区间，写本CTA只读包表。每CTA严格q/q+1包，先取自己的claimrow包，超额按prefix填缺口。无额外grid barrier、无动态逐包CAS/全局服务队列、无串行greedy规划。原unique页、真实stage/cache双写、包级release/acquire、全8warp数学与精确LRU保持。区别于旧poolquota：不是按pool粗划，也不由每CTA leader反复重建localfirst+spill greedy；是复用现有shared row prefix的并行计数/scan/逆映射。每包仍有只读列表查询成本，规划及全部global写入均在kernel事件内。\n\n180CPU随机含unique0/不同CTA数/不整包证明exact partition及q/q+1；真实先导末步可保留7557/8875包在claimrow CTA，1318包溢出。GPU原型unique0直接返回planner，不读resolve未发布的旧global rowbase，避免重犯旧poolquota零miss问题。新增partial backing长度和planner shared边界检查。\n\n实际GPU最终包表8857项，逐项等于用本次actual rowbase重新构造的CPU映射，完整0..8856恰一次，ready flags epoch匹配；108CTA配额82/83，保留7621包，溢出1236包。该步far引用348379、自用147704（42.3975%），同remap原轮转为3158（0.9065%）。这些是完整kernel实际planner/载荷协议的验证，不是硬件远端计数器证明。两项K65/K2048数学/LSE/Graph/cache载荷定向检查通过；性能数学采样和全部最终有效cache载荷通过，容差未变。\n\n正常GPU3/A100-PCIE/NUMA1同卡独立HBM源，BF16/h64/MTP8/R128/K2048/LRU4096，256位置32步×3coldpass {means}µs，均{a['mean_us']:.6f}。未优近期clean3099.381或生产staged约3029；不安装，不扩展100GB模拟，不宣称全CTA unique方案已胜出。相对旧串行poolquota约3540更快仅为跨轮不同方案描述，不能当单项因果收益。主函数REG255/STACK16/static1280（原1152），同统计器10638指令；未分离planner、包序、列表查询或服务时序的动态成本，不能凭更高自用率推断更快。\n\nraw、实际header/加载库SHA、CPU模型、首导出及全部计时保留。无新全矩阵/sanitizer/FP16/物理PCIe/NVLink/H800结论；正常far_rows0仅禁用计数，不是零远端载荷。生产三个header未改。\n''')
h=root/'docs/HANDOFF.md';s=h.read_text();marker='## 2. 当前运行状态与新一轮进度\n';assert marker in s;s=s.replace(marker,marker+'''\n**11/04认领行并行配额新机制：** 原kernel实际rowprefix诊断认领行owner自用0.90%→49.01%、首far pair producer13.37→5.11，但每CTA30–160包尾部不可直接用。新planner复用resolve shared rowprefix，线程并行owner计数+excess/deficit scan+逆区间映射，无额外grid barrier/串行greedy；180CPU partition通过，实际GPU包表8857项与CPU逐项一致/epoch匹配，严格82/83包，自用42.40%。2定向检查及全cache载荷通过，normal3pass3200.331µs仍慢clean，拒绝不测100GB。区别旧poolquota的规划算法与成本，不能把更高自用当收益；未分离动态成本。见CLAIMROW_QUOTA_20261104.md、audit/model/raw/实际库SHA。生产81093保持，runner结束。\n\n**11/04CTA-owned行计数实验：** prepare_parts1/segment<=2048，warp计数atomicAdd换CTA prefix/direct store；页级CAS/EXCH不动，多分片回退原prepare。384CPU rankcase、2GPU定向通过，normal3095.413µs对近期clean3099.381仅0.13%，unique均值215559.54对215250.02略变，不认定收益/不安装。源/实际库SHA见CTA_ROW_COUNTS_20261104.md及audit，无新100GB结论。\n''');h.write_text(s)
production={x:hashlib.sha256((root/'include/flashinfer/attention'/x).read_bytes()).hexdigest() for x in ['mla_host_batch.cuh','mla.cuh','far_link_emu.cuh']};assert production['mla_host_batch.cuh']=='81093ba5ab33cc5d84b2df04c702975697387b4054ebe8f1991f558f1bd6cdd2'
files=[root/x for x in subprocess.check_output(['git','ls-files','--others','--exclude-standard',str(p.relative_to(root))],cwd=root,text=True).splitlines()]
for f in files:
 if f.suffix=='.py':ast.parse(f.read_text())
 if f.suffix=='.json':json.loads(f.read_text())
m=p/'claimrow_20261104_manifest.json';m.write_text(json.dumps(dict(files=[dict(path=str(f.relative_to(root)),sha256=hashlib.sha256(f.read_bytes()).hexdigest(),bytes=f.stat().st_size) for f in files],verified_raw=verified,production=production),indent=2)+'\n')
subprocess.run(['git','add','--',*[str(f.relative_to(root)) for f in files],str(m.relative_to(root)),'docs/HANDOFF.md'],cwd=root,check=True);print(len(files),'files; verified',verified)
